css_snippet:
h1, .hero-heading {
    font-family: "Inter", sans-serif;
    font-size: 3rem;
    line-height: 1.2;
    text-wrap: balance; /* The magic touch for balanced lines */
    color: #1a1a1a;
}

p.intro-text {
    font-family: "Roboto", sans-serif;
    font-size: 1.15rem;
    line-height: 1.6;
    max-width: 60ch; /* Optimal line length for readability */
    text-wrap: pretty; /* Or balance if it's very short */
}
